plt.figure(figsize=(12, 8))

for name, data in algorithms.items():
    # Plot median line
    plt.plot(n, data['median'], 
             marker=data['marker'],
             color=data['color'],
             label=f'{name} (median)',
             linewidth=2.5,
             markersize=9,
             markeredgecolor='white',
             markeredgewidth=1.5)
    
    # Fill interquartile range (25-75%)
    plt.fill_between(n, data['q10'], data['q90'],
                     color=data['color'],
                     alpha=0.2,
                     label=f'{name} (IQR)')

